#include<iostream>
#include<vector>
#include<string>
#include <utility> 
#include <sstream>
#include<algorithm>
using namespace std;
​
int main() {
    int sum = 0;

    int tmp;
    vector<int> ans;
    // 处理接收数据
    while (cin >> tmp) {
        sum += tmp;
        ans.push_back(tmp);
    }
    int len = ans.size();
    int base = len * 128;
    // 确定 平均差值
    int diff = (sum - base) / len;
​
    int res;
    int last = -1;
    // diff < 0 说明值k为正数
    if (diff < 0) {
        diff = -diff;
        for (; ; diff++) {
            int currentSum = 0;
            for (int i = 0; i < len; i++) {
                currentSum += min(255, ans[i] + diff);
            }
            // 随着diff变大，求和的值肯定是递增的 取小的数
            if (abs(currentSum - base) >= abs(last - base)) {
                break;
            }
            last = currentSum;
            res = diff;
        }
    // 说明k为负数    
    } else if (diff > 0){
        for (; ; diff++) {
            int currentSum = 0;
            for (int i = 0; i < len; i++) {
                currentSum += max(0, ans[i] - diff);
            }
            // 不是等号是需要取下面的数的原因，比如 -1 和 -2 差异都相同时要取-2
            if (abs(currentSum - base) > abs(last - base)) {
                break;
            }
            last = currentSum;
            res = -diff;
        }
    } else {
        cout << 0;
    }
​
    cout << res;
    return 0;
}

