public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<Integer> ans = new ArrayList<>();
        int sum = 0;
​
        // 处理接收数据
        while (scanner.hasNextInt()) {
            int tmp = scanner.nextInt();
            sum += tmp;
            ans.add(tmp);
        }
        scanner.close();
​
        int len = ans.size();
        int base = len * 128;
        int diff = (sum - base) / len;
        int res = 0;
        int last = -1;
​
        // diff < 0 说明 k 为整数
        if (diff < 0) {
            diff = -diff;
            while (true) {
                int currentSum = 0;
                for (int num : ans) {
                    currentSum += Math.min(255, num + diff);
                }
                // 随着diff变大，求和的值肯定是递增的 取小的数
                if (Math.abs(currentSum - base) >= Math.abs(last - base)) {
                    break;
                }
                last = currentSum;
                res = diff;
                diff++;
            }
        }
        // diff > 0 说明 k 为负数
        else if (diff > 0) {
            while (true) {
                int currentSum = 0;
                for (int num : ans) {
                    currentSum += Math.max(0, num - diff);
                }
                // 不是等号是需要取下面的数的原因，比如 -1 和 -2 差异都相同时要取-2
                if (Math.abs(currentSum - base) > Math.abs(last - base)) {
                    break;
                }
                last = currentSum;
                res = -diff;
                diff++;
            }
        } else {
            System.out.println(0);
            return;
        }
​
        System.out.println(res);
    }
}
