package main
​
import (
    "fmt"
    "math"
)
​
func main() {
    // 读取输入
    var sum, tmp int
    var ans []int
​
    // 处理接收数据
    for {
        _, err := fmt.Scan(&tmp)
        if err != nil {
            break
        }
        sum += tmp
        ans = append(ans, tmp)
    }
​
    lenAns := len(ans)
    base := lenAns * 128
​
    // 计算 diff
    diff := (sum - base) / lenAns
​
    res := 0
    last := -1
​
    // diff < 0 说明 k 为整数
    if diff < 0 {
        diff = -diff
        for {
            currentSum := 0
            for _, v := range ans {
                currentSum += int(math.Min(255, float64(v+diff)))
            }
            // 随着diff变大，求和的值肯定是递增的 取小的数
            if last != -1 && int(math.Abs(float64(currentSum-base))) >= int(math.Abs(float64(last-base))) {
                break
            }
            last = currentSum
            res = diff
            diff++
        }
    } else if diff > 0 { // 说明 k 为负数
        for {
            currentSum := 0
            for _, v := range ans {
                currentSum += int(math.Max(0, float64(v-diff)))
            }
            // 需要取到较小的值， 负数是越往后越小， 正数是越往后越大
            if last != -1 && int(math.Abs(float64(currentSum-base))) > int(math.Abs(float64(last-base))) {
                break
            }
            last = currentSum
            res = -diff
            diff++
        }
    } else {
        fmt.Println(0)
        return
    }
​
    fmt.Println(res)
}
